# Custom handler for console that can toggle between clean and detailed mode                                                                                                                                                                                      
class ToggleableStreamHandler(logging.StreamHandler):                                                                                                                                                                                                             
    def __init__(self, stream=None):                                                                                                                                                                                                                              
        super().__init__(stream)                                                                                                                                                                                                                                  
        self.setFormatter(standard_formatter)                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                  
    def emit(self, record):                                                                                                                                                                                                                                       
        # When in clean output mode, only show system messages (not transcriptions)                                                                                                                                                                               
        if CLEAN_OUTPUT_MODE and hasattr(record, 'transcription'):                                                                                                                                                                                                
            # Skip printing transcription logs in console handler                                                                                                                                                                                                 
            # (they are printed directly in log_transcription function)                                                                                                                                                                                           
            return                                                                                                                                                                                                                                                
        else:                                                                                                                                                                                                                                                     
            # Standard logging behavior for debug/system messages                                                                                                                                                                                                 
            super().emit(record)                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                  
# Add console handler with custom formatter                                                                                                                                                                                                                       
console_handler = ToggleableStreamHandler(sys.stdout)                                                                                                                                                                                                             
logger.addHandler(console_handler)                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                  
# Convenience function to log clean transcriptions                                                                                                                                                                                                                
def log_transcription(text, session_id=None):                                                                                                                                                                                                                     
    """Log transcription text in clean format when clean mode is enabled"""                                                                                                                                                                                       
    if CLEAN_OUTPUT_MODE:                                                                                                                                                                                                                                         
        # In clean mode, print directly to stdout without additional formatting                                                                                                                                                                                   
        print(text, flush=True)                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                  
    # Always log to file with standard formatting                                                                                                                                                                                                                 
    # Create a record with a special attribute                                                                                                                                                                                                                    
    record = logging.LogRecord(                                                                                                                                                                                                                                   
        name=logger.name,                                                                                                                                                                                                                                         
        level=logging.INFO,                                                                                                                                                                                                                                       
        pathname='',                                                                                                                                                                                                                                              
        lineno=0,                                                                                                                                                                                                                                                 
        msg=f"Session {session_id}: Transcribed text: '{text}'",                                                                                                                                                                                                  
        args=(),                                                                                                                                                                                                                                                  
        exc_info=None                                                                                                                                                                                                                                             
    )                                                                                                                                                                                                                                                             
    # Add custom attribute for our handler to detect                                                                                                                                                                                                              
    record.transcription = text                                                                                                                                                                                                                                   
    logger.handle(record)                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                  
